import React from "react";
import useGetLatest from "./useGetLatest";

// FIXME implement a version working with arrays of components ?

export default function useTimeout(callback?: Function, delay?: number) {
  const getLatest = useGetLatest({ callback });

  const startTime = React.useRef(0);
  React.useEffect(() => {
    startTime.current = performance.now();
  }, []);

  React.useEffect(() => {
    if (typeof delay !== "number") return;

    const diff = performance.now() - (startTime.current || 0);
    const timer = setTimeout(() => {
      const { callback } = getLatest();
      callback();
    }, delay - diff);
    return () => clearTimeout(timer);
  }, [delay, getLatest]);
}
